import { contextBridge, ipcRenderer } from "electron";
import { ALLOWED_INVOKE, ALLOWED_LISTEN } from "@qiwork/desktop-runtime/ipcEvents";

contextBridge.exposeInMainWorld("electronAPI", {
  invoke: (channel: string, args?: unknown) => {
    if (!ALLOWED_INVOKE.has(channel)) {
      return Promise.reject(new Error(`ipc blocked: ${channel}`));
    }
    return ipcRenderer.invoke(channel, args);
  },
  listen: (channel: string, callback: (payload: unknown) => void) => {
    if (!ALLOWED_LISTEN.has(channel)) {
      return () => {};
    }
    const sub = (_event: Electron.IpcRendererEvent, payload: unknown) => {
      callback(payload);
    };
    ipcRenderer.on(channel, sub);
    return () => ipcRenderer.removeListener(channel, sub);
  },
  platform: process.platform as "darwin" | "win32" | "linux",
  runtime: {
    electron: process.versions.electron ?? "",
    chrome: process.versions.chrome ?? "",
    node: process.versions.node ?? "",
    v8: process.versions.v8 ?? "",
    arch: process.arch,
  },
});
